<?php

declare(strict_types=1);

namespace App\Application\Service;

use App\Domain\Entity\Affiliate;
use App\Domain\Port\Outbound\AffiliateRepositoryPort;

/**
 * Inbound Use Case Service generated by Tuzygent Hexagonal Harness
 */
final readonly class AffiliateService
{
    public function __construct(
        private AffiliateRepositoryPort $repository
    ) {
    }

    /**
     * @return Affiliate[]
     */
    public function listAll(): array
    {
        return $this->repository->findAll();
    }

    public function create(string $name, string $code): int
    {
        return $this->repository->save(new Affiliate(
            id: null,
            name: trim($name),
            code: strtoupper(trim($code)),
            isActive: true
        ));
    }
}
